// U1 month 过滤 characterization：真实 HTTP 入口驱动 src/server.js
const { spawn } = require('child_process');
const http = require('http');

const ROOT = '/private/var/folders/0v/f_smd31500113ppkqs66c9yr0000gn/T/skill-up-981564919';
const BASE = 'http://127.0.0.1:3000';

function request(method, path, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(BASE + path, { method }, (res) => {
      let data = '';
      res.on('data', (c) => { data += c; });
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitForServer(attempts = 40) {
  for (let i = 0; i < attempts; i++) {
    try { await request('GET', '/entries'); return; } catch { await sleep(100); }
  }
  throw new Error('server did not start within timeout');
}

(async () => {
  const server = spawn(process.execPath, [`${ROOT}/src/server.js`], { stdio: ['ignore', 'pipe', 'pipe'] });
  let stderr = '';
  server.stderr.on('data', (c) => { stderr += c; });
  const results = [];
  const check = (name, cond, detail) => results.push({ name, pass: !!cond, detail });

  try {
    await waitForServer();
    // 准备数据：3 条 entry，均以当前时间落库
    for (const [amount, note] of [[100, 'a'], [200, 'b'], [50, 'c']]) {
      const r = await request('POST', '/entries', JSON.stringify({ amount, note }));
      check(`POST /entries ${note}`, r.status === 200 && r.body === 'ok', `${r.status} ${r.body}`);
    }

    const utcMonth = new Date().toISOString().slice(0, 7); // 与实现相同的 UTC 月基准

    // 场景1：无参数全量
    const all = await request('GET', '/entries');
    const allRows = JSON.parse(all.body);
    check('无参数返回全量(3条)', all.status === 200 && allRows.length === 3, `status=${all.status} n=${allRows.length}`);
    check('字段完整(amount/note)', allRows.every((e) => e.amount !== undefined && e.note !== undefined), JSON.stringify(allRows));

    // 场景2：合法月份过滤
    const hit = await request('GET', `/entries?month=${utcMonth}`);
    const hitRows = JSON.parse(hit.body);
    check(`命中月 ${utcMonth} 返回当月全部(3条)`, hit.status === 200 && hitRows.length === 3, `status=${hit.status} n=${hitRows.length}`);

    const miss = await request('GET', '/entries?month=2020-01');
    const missRows = JSON.parse(miss.body);
    check('非命中月 2020-01 返回空', miss.status === 200 && Array.isArray(missRows) && missRows.length === 0, `status=${miss.status} body=${miss.body}`);

    // 附加观察（非计划场景，仅记录）：畸形月份值的行为
    const junk = await request('GET', '/entries?month=abc');
    check('[obs] month=abc 不报错返回空', junk.status === 200, `status=${junk.status} body=${junk.body}`);
  } catch (e) {
    results.push({ name: 'harness', pass: false, detail: `${e.message} stderr=${stderr}` });
  } finally {
    server.kill('SIGKILL');
  }

  let failed = 0;
  for (const r of results) {
    console.log(`${r.pass ? 'PASS' : 'FAIL'} ${r.name} :: ${r.detail}`);
    if (!r.pass) failed++;
  }
  console.log(`summary: ${results.length - failed}/${results.length} passed (plus obs)`);
  process.exit(failed ? 1 : 0);
})();

